from pathlib import Path
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError
from concurrent.futures import ThreadPoolExecutor
import json

ROOT = Path(r'<USER_HOME>\Documents\Codex\2026-10-25\new-chat\work\erdos99\sources')
ROOT.mkdir(parents=True, exist_ok=True)
SOURCES = [
    ('erdos-1994.pdf', 'https://mathematica-pannonica.ttk.pte.hu/articles/mp05-2/mp05-2-261-269.pdf'),
    ('bateman-erdos-1951.pdf', 'https://renyi.hu/~p_erdos/1951-03.pdf'),
    ('das-2026.pdf', 'https://zenodo.org/records/22768362/files/erdos99_stress_rhombic_reductions_dcg_final.pdf?download=1'),
]

def fetch(source):
    filename, url = source
    path = ROOT / filename
    if path.exists():
        return {'name': filename, 'status': 'existing', 'bytes': path.stat().st_size}
    try:
        req = Request(url, headers={'User-Agent': 'Mozilla/5.0 (research source verification)'})
        with urlopen(req, timeout=25) as response:
            data = response.read(5_000_000)
            kind = response.headers.get('Content-Type', '')
        if not data.startswith(b'%PDF'):
            return {'name': filename, 'status': 'not_pdf', 'content_type': kind, 'prefix': data[:120].decode('utf-8', 'replace')}
        path.write_bytes(data)
        return {'name': filename, 'status': 'saved', 'bytes': len(data), 'path': str(path)}
    except (HTTPError, URLError, TimeoutError) as exc:
        return {'name': filename, 'status': 'error', 'detail': str(exc)}

with ThreadPoolExecutor(max_workers=3) as pool:
    results = list(pool.map(fetch, SOURCES))
print(json.dumps(results))
try:
    from pypdf import PdfReader
except ImportError:
    print(json.dumps({'extraction': 'pypdf unavailable'}))
else:
    for entry in results:
